INSERT INTO metric_definitions (metric_key, version, label, surface, unit, confidence, formula, session_basis, basis_label, grains, direction, comparison_mode, treatment, source_tables, effective_from, effective_to, change_note, created_at) VALUES
  ('units_sold_since_drop', 1, 'Units sold since drop', 'product', 'count', 'measured', 'units on non-excluded orders from drop day 0 through the day shown', NULL, 'Shopify units', '["product","variant","size","drop"]', 'higher_better', 'drop_day', 'Counted by the order''s own drop and drop-day, so day 3 of one drop is day 3 of another. Cancelled orders stay in until they are excluded by rule.', '["fact_order_line","fact_order","dim_drop"]', '1970-01-02', NULL, 'v1: added with the drop view (founder question 5).', '2026-09-12T00:00:00Z'),
  ('full_price_sell_through', 2, 'Full-price sell-through', 'product', 'ratio', 'measured', 'units sold at full price since drop_date ÷ units committed', NULL, NULL, '["product","variant","drop"]', 'higher_better', 'drop_day', NULL, '["fact_order_line","dim_drop","fact_inventory_daily"]', '1970-01-02', NULL, 'v2: adds the drop grain for the drop view. Meaning unchanged, so it governs all history.', '2026-09-16T00:00:00Z'),
  ('discounted_sell_through', 2, 'Discounted sell-through', 'product', 'ratio', 'measured', 'units sold at a discount since drop_date ÷ units committed', NULL, NULL, '["product","variant","drop"]', 'neutral', 'drop_day', NULL, '["fact_order_line","dim_drop","fact_inventory_daily"]', '1970-01-02', NULL, 'v2: adds the drop grain for the drop view. Meaning unchanged, so it governs all history.', '2026-09-16T00:00:00Z'),
  ('units_committed', 1, 'Units committed at launch', 'product', 'count', 'measured', 'qty_on_hand at the last stock snapshot before drop_date, at locations that fulfil online orders', NULL, 'Stock snapshot', '["product","variant","size","drop"]', 'neutral', 'none', 'Snapshots began 2026-09-14, so drops before then have no commitment and sell-through is missing, not zero. Stock at locations not marked as fulfilling online orders is left out; unclassified locations lower coverage.', '["fact_inventory_daily","dim_drop"]', '1970-01-02', NULL, 'v1: added with the drop view (founder question 5).', '2026-09-12T00:00:00Z');
